// @vegastack board@0.19.0 sha256-OWAZlhjyGdeImGDjWmHFUIFX4Koode8BaFRRgVwjWqY=

"use client";

import * as React from "react";
import { EllipsisVertical } from "lucide-react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cn } from "@vegastack/design";
import { dragItemClasses } from "@/lib/drag-item";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  RowActionMenuItems,
  type RowAction,
} from "@/components/ui/data-table-parts";
import { LoadMore, type LoadMoreState } from "@/components/ui/load-more";
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Skeleton } from "@/components/ui/skeleton";
import { TruncationFocusProvider } from "@/components/ui/truncated-text";
import { useIsMobile } from "@/components/ui/use-mobile";
import {
  useDragReorder,
  type DragReorderAnnouncements,
  type DragReorderMove,
} from "@/components/ui/use-drag-reorder";

// Bundlers replace `process.env.NODE_ENV` at build time; declared here so consumers without
// @types/node still type-check the dev-only warning below.
declare const process: { env: { NODE_ENV?: string } };

/* ---
`Board` owns column layout, the drag/move model, the keyboard-and-menu equivalent, and
the pending/rejected affordances — the host renders card CONTENT only and owns the
move command. That content/chrome split is the cleanest boundary in the reference
implementation and is inherited deliberately: the component owns all chrome (column
shells, counts, empty drop targets, collapsed strips), the app owns what a card says.

The keyboard path is not a fallback here — below 768px drag is disabled outright
(engine drags are pointer-first and fight touch scrolling), so the "Move to…" menu and
the handle's move mode are the ONLY paths on mobile and must be lossless by
construction. Every card's menu lists every droppable column with per-target lock
reasons; `M` on a focused card opens it directly.

Elevation: a dragged card gains no shadow. Lift is expressed by dimming the ORIGIN card,
and the thing under the pointer is the browser's own drag preview — a flat snapshot taken
before any drag class lands — so a shadow on the source would not appear on the moving
image anyway. Separation comes from the card's hairline against the column ground. (The
blanket shadow ban this used to cite is gone with Batch 1 of the shadcn reset; what
remains is the mechanical reason, not the doctrine.)

Deliberately NOT done here:
- No card focus-roving via `use-list-nav` — its grid model assumes uniform columns and
  a board is ragged. The small board-specific roving model below (↑/↓ within a column,
  ←/→ across columns at a clamped index — the reference's cross-column behaviour) is
  more honest than contorting the hook. Cards keep one Tab stop per board.
- No data behaviour: ordering, persistence, and the move command are the host's
  (`onMove` may return a promise → pending shimmer, announced snap-back on rejection).
- No virtualization — columns are bounded by design at this component's scale.
- No custom drag-preview portal. The native preview is the flat card snapshot; a
  custom `z-50` portal preview is a consumer option, not built-in chrome.
--- */

/** One board column. */
export interface BoardColumn<T> {
  /** Stable column id — the container identity moves target. */
  id: string;
  /** Column heading content. */
  title: React.ReactNode;
  /**
   * Plain-text lane name — used in the lane's accessible name, the "Move to…"
   * menu and every announcement. Required when `title` is not a string (a
   * `Badge`, an icon + text): the board cannot read a name out of a node, and
   * warns in development when it has to fall back to the column `id`.
   * @default the `title` when it is a string
   */
  label?: string;
  /** Cards in display order (controlled) — the loaded cards of a paged lane. */
  items: readonly T[];
  /**
   * The lane's total, when it holds more than it has loaded. Shown as the
   * lane's muted count and spoken in its name ("Open, 14 tasks").
   * @default items.length
   */
  count?: number;
  /**
   * The lane is fetching: skeleton cards show below any loaded cards (in
   * place of the empty state) and the lane is `aria-busy`.
   * @default false
   */
  loading?: boolean;
  /**
   * What an empty lane shows, replacing the default "No cards" drop target.
   * Pass an `Empty className="border"` to keep the drop-zone look.
   * @default undefined
   */
  emptyState?: React.ReactNode;
  /**
   * Whether cards can be dropped into (or moved to) this column. A parked
   * lane sets `false` — it still renders, but is never a target.
   * @default true
   */
  droppable?: boolean;
  /**
   * Reason shown (and announced) for an unavailable move target — pairs with
   * `droppable: false` or business gating.

   * @default undefined
   */
  lockedReason?: string;
  /**
   * Start collapsed to a narrow strip (terminal columns). Activating the
   * strip expands the column read-only: cards show but do not drag, and it is
   * not a drop target.
   * @default false
   */
  defaultCollapsed?: boolean;
  /**
   * Alias of `defaultCollapsed`, kept for existing boards.
   * @deprecated Use `defaultCollapsed`.
   * @default false
   */
  collapsed?: boolean;
  /**
   * Keyset paging for this lane: the shared `LoadMore` footer after the lane's cards, inside
   * its scroll.
   * @default undefined
   */
  loadMore?: LoadMoreState;
}

/** Props accepted by `Board`. */
export interface BoardProps<T> {
  /** Columns in display order. */
  columns: readonly BoardColumn<T>[];
  /** Stable card identity. */
  getItemId: (item: T) => string;
  /**
   * Render a card's CONTENT only — the board owns the card chrome (surface,
   * border, focus, drag affordances).
   */
  renderCard: (item: T, column: BoardColumn<T>) => React.ReactNode;
  /**
   * Apply a move (drag, keyboard, or menu). Return a promise for server-gated
   * moves: the card shimmers in place while pending, and a rejection announces
   * the snap-back (the host never applied it).
   */
  onMove: (move: DragReorderMove) => void | Promise<void>;
  /**
   * Plain-text card name — used in the card's menu control ("Move Write
   * spec") and in move announcements. Without it the control is "Move card"
   * and announcements say "card".
   * @default undefined
   */
  getItemLabel?: (item: T) => string;
  /**
   * A card's own actions (open, edit, archive), listed first in its ⋯ menu, above a separator
   * and the Move items — one menu per card.
   * @default undefined
   */
  getItemActions?: (item: T) => RowAction[];
  /**
   * The lane's count in words, for the lane's accessible name ("Open, 14
   * tasks"). Name the host's noun here.
   * @default (n) => n === 1 ? "1 card" : `${n} cards`
   */
  countLabel?: (n: number) => string;
  /**
   * Make a card a real link. A card with an href renders as an `<a>` (or
   * `itemLinkRender`): a click, Enter, and every modifier click are the
   * browser's own, and `onCardActivate` is not called for it. Space still
   * lifts it into move mode. Keep card content free of links and buttons.
   * @default undefined
   */
  getItemHref?: (item: T) => string | undefined;
  /**
   * The element a card link renders — a router link such as `<Link />`. It
   * receives the `href`, the board's props and the card content.
   * @default <a />
   */
  itemLinkRender?: React.ReactElement;
  /**
   * Activate a card (open its record). Cards without an href render as real
   * buttons; a card with one is a link and never calls this.

   * @default undefined
   */
  onCardActivate?: (item: T) => void;
  /**
   * Column width as a CSS length, applied through the `--board-column-width`
   * custom property.
   * @default "18rem"
   */
  columnWidth?: string;
  /**
   * Maximum height of a column's scrolling card list, as a CSS length, applied
   * through the `--board-column-max-height` custom property. The default is the
   * shared overlay ceiling token — a board inside a shorter shell passes its own
   * length rather than the component assuming a viewport reservation.
   * @default "calc(100dvh - 16rem)"
   */
  columnMaxHeight?: string;
  /**
   * Extra per-column header action (a filter menu, an add button) rendered in
   * the column's `CardAction` seat.

   * @default undefined
   */
  renderColumnAction?: (column: BoardColumn<T>) => React.ReactNode;
  /**
   * Force-disable dragging (the menu and move mode remain). Dragging is
   * always disabled below 768px.
   * @default false
   */
  dragDisabled?: boolean;
  /**
   * Accessible name for the board.
   * @default "Board"
   */
  "aria-label"?: string;
  /** Extra classes for the board root.
   * @default undefined
   */
  className?: string;
  /**
   * Ref forwarded to the board root (`data-slot="board"`).

   * @default undefined
   */
  ref?: React.Ref<HTMLDivElement>;
}

/** The plain-text name of a lane: its `label`, else a string `title`, else its `id`. */
function laneLabel<T>(column: BoardColumn<T>): string {
  if (column.label !== undefined) return column.label;
  return typeof column.title === "string" ? column.title : column.id;
}

/** Sentence case for a label that opens an announcement. */
function upperFirst(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

/** "1 card" / "4 cards" — the lane's count in words. */
function cardCount(n: number): string {
  return `${n} ${n === 1 ? "card" : "cards"}`;
}

/** Props for the internal card surface. */
interface BoardCardSurfaceProps extends React.HTMLAttributes<HTMLElement> {
  href?: string;
  linkRender?: React.ReactElement;
  ref?: React.Ref<HTMLElement>;
}

/**
 * The card surface: a `role="button"` div, or — with an `href` — a link
 * rendered through `linkRender` (default `<a />`). The link is not natively
 * draggable, so a pointer drag starts from the card, not from the URL.
 */
function BoardCardSurface({
  href,
  linkRender,
  ref,
  ...props
}: BoardCardSurfaceProps) {
  return useRender({
    defaultTagName: "div",
    render: href ? (linkRender ?? <a />) : undefined,
    ref,
    props: mergeProps<"div">(
      href
        ? ({ href, draggable: false } as React.ComponentProps<"div">)
        : { role: "button" },
      props,
    ),
  });
}

/**
 * `Board` — kanban columns over `use-drag-reorder`: pointer drag with
 * closest-edge indicators, the keyboard move mode on each card's handle-free
 * surface (Space lifts the focused card), the lossless per-card "Move to…"
 * menu (<kbd>M</kbd> opens it), cross-column roving focus (↑/↓ within, ←/→
 * across), pending shimmer + announced snap-back for server-refused moves,
 * collapsed terminal columns, and `Empty className="border"` drop targets for empty
 * columns. The host renders card content and owns the move command.
 *
 * @example
 * <Board
 *   aria-label="Deals"
 *   columns={stages.map((s) => ({ id: s.id, title: s.label, items: s.deals }))}
 *   getItemId={(deal) => deal.id}
 *   renderCard={(deal) => <>{deal.name} · {deal.amount}</>}
 *   onMove={({ id, to }) => api.moveDeal(id, to.container, to.index)}
 * />
 */
export function Board<T>({
  columns,
  getItemId,
  renderCard,
  onMove,
  getItemLabel,
  getItemActions,
  countLabel = cardCount,
  getItemHref,
  itemLinkRender,
  onCardActivate,
  columnWidth = "18rem",
  columnMaxHeight = "calc(100dvh - 16rem)",
  renderColumnAction,
  dragDisabled = false,
  "aria-label": ariaLabel = "Board",
  className,
  ref,
}: BoardProps<T>) {
  const isMobile = useIsMobile();
  const [expandedOverrides, setExpandedOverrides] = React.useState<
    ReadonlySet<string>
  >(new Set());
  const [openMenuCard, setOpenMenuCard] = React.useState<string | null>(null);

  const declaredCollapsed = (column: BoardColumn<T>) =>
    column.defaultCollapsed ?? column.collapsed ?? false;
  const isCollapsed = (column: BoardColumn<T>) =>
    declaredCollapsed(column) && !expandedOverrides.has(column.id);
  /** Columns declared collapsed stay read-only even while expanded to view. */
  const isReadOnly = (column: BoardColumn<T>) => declaredCollapsed(column);
  /** "Open, 14 tasks" — the lane's accessible name, from its total. */
  const laneName = (column: BoardColumn<T>) =>
    `${laneLabel(column)}, ${countLabel(column.count ?? column.items.length)}`;

  const lists = React.useMemo(() => {
    const record: Record<string, string[]> = {};
    for (const column of columns)
      record[column.id] = column.items.map(getItemId);
    return record;
  }, [columns, getItemId]);

  const itemsById = React.useMemo(() => {
    const map = new Map<string, { item: T; column: BoardColumn<T> }>();
    for (const column of columns)
      for (const item of column.items)
        map.set(getItemId(item), { item, column });
    return map;
  }, [columns, getItemId]);

  // Pointer drags are off on mobile and by prop; the card surface reads the SAME flag for its
  // cursor, so the grab affordance can never promise a drag the engine will refuse (audit B8-06).
  const pointerDisabled = dragDisabled || isMobile;

  // A lane whose title is a node has no name to read unless the host gives one.
  React.useEffect(() => {
    if (process.env.NODE_ENV === "production") return;
    for (const column of columns)
      if (column.label === undefined && typeof column.title !== "string")
        console.warn(
          `Board: column "${column.id}" has a non-string title and no \`label\`; its accessible name falls back to the id.`,
        );
  }, [columns]);

  const columnsById = new Map(columns.map((column) => [column.id, column]));
  const cardLabel = (id: string) => {
    const entry = itemsById.get(id);
    return entry && getItemLabel ? getItemLabel(entry.item) : "card";
  };
  const laneLabelById = (container: string) => {
    const column = columnsById.get(container);
    return column ? laneLabel(column) : container;
  };
  // Every announcement names the card and the lane, never a column id.
  const announcements: DragReorderAnnouncements = {
    lifted: ({ id, position, count, container }) =>
      `Move mode on. ${upperFirst(cardLabel(id))}, ${position} of ${count} in ${laneLabelById(container)}. Use the arrow keys to move, Escape to finish`,
    moved: ({ id, from, to, count }) =>
      from.container === to.container
        ? `Moved ${cardLabel(id)} to position ${to.index + 1} of ${count}`
        : `Moved ${cardLabel(id)} to ${laneLabelById(to.container)}, position ${to.index + 1} of ${count}`,
    ended: () => "Move mode off",
    rejected: ({ id, from }) =>
      `Move rejected — ${cardLabel(id)} stays in ${laneLabelById(from.container)}`,
  };

  const reorder = useDragReorder({
    announcements,
    lists,
    onReorder: onMove,
    axis: "vertical",
    // Pointer drags disable on mobile / by prop; the keyboard move mode and
    // the Move menu — the lossless paths — always survive.
    pointerDisabled,
    disabled: (id) => {
      const owner = itemsById.get(id)?.column;
      return owner ? isReadOnly(owner) : true;
    },
    // Locked lanes must refuse POINTER drops on their cards too — the
    // container ref gating alone leaves every card a valid target.
    canDropInContainer: (containerId) => {
      const column = columns.find((c) => c.id === containerId);
      return column ? column.droppable !== false && !isReadOnly(column) : false;
    },
  });

  // ---- roving focus across the ragged card grid ----------------------------
  const [activeCard, setActiveCard] = React.useState<string | null>(null);
  const cardRefs = React.useRef(new Map<string, HTMLElement>());
  const visibleColumns = columns.filter((column) => !isCollapsed(column));
  const firstCardId = visibleColumns.flatMap((column) =>
    column.items.map(getItemId),
  )[0];
  // Reconcile the roving target against the CURRENT card set: if the active
  // card was removed (poll, filter) or its column collapsed, fall back to the
  // first card — otherwise the board loses its only tab stop permanently.
  const activeCardStillVisible =
    activeCard !== null &&
    visibleColumns.some((column) =>
      column.items.some((item) => getItemId(item) === activeCard),
    );
  const rovingTarget =
    (activeCardStillVisible ? activeCard : null) ?? firstCardId ?? null;

  const focusCard = React.useCallback((id: string | undefined) => {
    if (!id) return;
    setActiveCard(id);
    cardRefs.current.get(id)?.focus();
  }, []);

  const handleCardKeyDown = (
    event: React.KeyboardEvent,
    column: BoardColumn<T>,
    index: number,
    id: string,
  ) => {
    // The move-mode handler (Space/arrows while lifted) runs first; browsing
    // keys below only apply when the card is not in move mode.
    if (reorder.activeId === id) return;
    const columnIndex = visibleColumns.findIndex((c) => c.id === column.id);
    switch (event.key) {
      case "ArrowDown":
      case "ArrowUp": {
        event.preventDefault();
        const delta = event.key === "ArrowDown" ? 1 : -1;
        const ids = column.items.map(getItemId);
        focusCard(ids[Math.max(0, Math.min(index + delta, ids.length - 1))]);
        break;
      }
      case "ArrowLeft":
      case "ArrowRight": {
        event.preventDefault();
        const isRtl = getComputedStyle(event.currentTarget).direction === "rtl";
        const logical = event.key === "ArrowRight" ? 1 : -1;
        const delta = isRtl ? -logical : logical;
        const next = visibleColumns[columnIndex + delta];
        if (!next || next.items.length === 0) return;
        const ids = next.items.map(getItemId);
        focusCard(ids[Math.min(index, ids.length - 1)]);
        break;
      }
      case "Home": {
        event.preventDefault();
        focusCard(column.items.map(getItemId)[0]);
        break;
      }
      case "End": {
        event.preventDefault();
        focusCard(column.items.map(getItemId).at(-1));
        break;
      }
      case "m":
      case "M": {
        event.preventDefault();
        setOpenMenuCard(id);
        break;
      }
      default:
        break;
    }
  };

  const moveTargetsFor = (id: string, from: BoardColumn<T>) =>
    columns
      .filter((column) => column.id !== from.id)
      .map((column) => ({
        column,
        locked: column.droppable === false || isReadOnly(column),
      }));

  return (
    <div
      ref={ref}
      data-slot="board"
      role="group"
      aria-label={ariaLabel}
      // Only a --* custom property — the class consumes it (contract-clean).
      style={
        {
          ["--board-column-width"]: columnWidth,
          ["--board-column-max-height"]: columnMaxHeight,
        } as React.CSSProperties
      }
      className={cn("w-full max-w-full min-w-0", className)}
    >
      <div
        data-slot="board-scroller"
        // w-full + max-w-full: inside a flex/grid parent the board must never
        // size to its columns' max-content — it scrolls internally instead
        // (the 320px reflow contract). The live region lives OUTSIDE this
        // scroller: an sr-only absolute element as the row's last child would
        // anchor at the row's content width and leak the page's scroll area.
        className="flex w-full max-w-full min-w-0 items-start gap-3 overflow-x-auto pb-2"
      >
        {columns.map((column) => {
          const collapsed = isCollapsed(column);
          const readOnly = isReadOnly(column);
          const containerProps = reorder.getContainerProps(column.id);
          if (collapsed) {
            return (
              <Button
                key={column.id}
                variant="outline"
                data-slot="board-column-collapsed"
                onClick={() =>
                  setExpandedOverrides((prev) => new Set(prev).add(column.id))
                }
                // `relative`: the sr-only child is absolutely positioned — without a
                // positioned ancestor it resolves against the ICB, and inside this
                // horizontally scrolled row its static x (~900px) would extend the
                // PAGE's scroll width (measured; the 320px reflow contract catches it).
                className="relative h-auto min-h-48 w-10 shrink-0 flex-col items-center gap-2 rounded-lg bg-card px-1 py-3"
              >
                <span
                  aria-hidden="true"
                  data-slot="board-column-count"
                  className="text-xs text-muted-foreground tabular-nums"
                >
                  {column.count ?? column.items.length}
                </span>
                <span
                  aria-hidden="true"
                  data-slot="board-column-collapsed-title"
                  className="min-h-0 flex-1 [writing-mode:vertical-rl] text-xs font-medium text-muted-foreground"
                >
                  {column.title}
                </span>
                <span className="sr-only">
                  {`${laneName(column)}. Expand column, read-only`}
                </span>
              </Button>
            );
          }
          return (
            <Card
              key={column.id}
              size="sm"
              role="region"
              aria-label={laneName(column)}
              aria-busy={column.loading ? true : undefined}
              data-slot="board-column"
              data-column={column.id}
              data-read-only={readOnly ? "" : undefined}
              data-drop-over={
                column.droppable === false || readOnly
                  ? undefined
                  : containerProps["data-drop-over"]
              }
              className={cn(
                "w-(--board-column-width) shrink-0 gap-2 bg-muted py-2",
                // The drop-over highlight recolours the CARD's hairline, which `Card` draws as a
                // real `border border-border` (BRD-1, ours since 23-09-2026). Between Batch 7c of
                // the shadcn reset and that reversal the hairline was upstream's `ring-1`, so this
                // read `ring-primary/50`; it must follow whichever one `Card` actually paints, or
                // it sets a colour on a zero-width edge and the drop affordance goes invisible.
                "data-drop-over:border-primary/50",
              )}
            >
              <CardHeader className="px-3">
                <CardTitle
                  data-slot="board-column-title"
                  className="flex min-w-0 items-center gap-2 text-xs font-medium text-muted-foreground"
                >
                  <span className="min-w-0 truncate">{column.title}</span>
                  <span
                    data-slot="board-column-count"
                    className="font-normal text-muted-foreground tabular-nums"
                  >
                    {column.count ?? column.items.length}
                  </span>
                </CardTitle>
                {renderColumnAction ? (
                  <CardAction>{renderColumnAction(column)}</CardAction>
                ) : null}
              </CardHeader>
              <CardContent className="px-2">
                <ScrollArea className="max-h-(--board-column-max-height)">
                  <div
                    data-slot="board-column-body"
                    ref={
                      column.droppable === false || readOnly
                        ? undefined
                        : containerProps.ref
                    }
                    className="flex min-h-16 flex-col gap-2 p-1"
                  >
                    {column.items.length === 0 ? (
                      // A loading lane is not empty yet: its skeletons stand in.
                      column.loading ? null : column.emptyState !==
                        undefined ? (
                        column.emptyState
                      ) : (
                        <Empty
                          className="border"
                          data-slot="board-column-empty"
                        >
                          <EmptyHeader>
                            <EmptyTitle>No cards</EmptyTitle>
                            {column.droppable === false ? (
                              <EmptyDescription>
                                {column.lockedReason ?? "Not a drop target"}
                              </EmptyDescription>
                            ) : !pointerDisabled && !readOnly ? (
                              // Only promise a drag where one can start: not
                              // under `dragDisabled`, below 768px, or read-only.
                              <EmptyDescription>
                                Drag a card here
                              </EmptyDescription>
                            ) : null}
                          </EmptyHeader>
                        </Empty>
                      )
                    ) : (
                      <div
                        role="list"
                        // The lane (region) carries the total; the list is
                        // named by the lane alone and counts its own items.
                        aria-label={laneLabel(column)}
                        className="flex flex-col gap-2"
                      >
                        {column.items.map((item, index) => {
                          const id = getItemId(item);
                          const itemActions = getItemActions?.(item) ?? [];
                          const itemProps = reorder.getItemProps(column.id, id);
                          const handleProps = reorder.getHandleProps(
                            column.id,
                            id,
                          );
                          const href = getItemHref?.(item);
                          const canDrag = !pointerDisabled && !readOnly;
                          return (
                            <div
                              key={id}
                              role="listitem"
                              ref={itemProps.ref}
                              data-drag-item={itemProps["data-drag-item"]}
                              data-dragging={itemProps["data-dragging"]}
                              data-drop-edge={itemProps["data-drop-edge"]}
                              data-drag-pending={itemProps["data-drag-pending"]}
                              data-slot="board-card"
                              // The ONE drag-item recipe, shared with SortableList.
                              className={dragItemClasses}
                            >
                              <BoardCardSurface
                                href={href}
                                linkRender={itemLinkRender}
                                tabIndex={rovingTarget === id ? 0 : -1}
                                ref={(node: HTMLElement | null) => {
                                  if (node) cardRefs.current.set(id, node);
                                  else cardRefs.current.delete(id);
                                  (
                                    handleProps.ref as (
                                      el: HTMLElement | null,
                                    ) => void
                                  )(node);
                                }}
                                data-slot="board-card-surface"
                                // A link has no pressed state; move mode is
                                // announced either way.
                                aria-pressed={
                                  href ? undefined : handleProps["aria-pressed"]
                                }
                                onFocus={() => setActiveCard(id)}
                                onBlur={handleProps.onBlur}
                                onKeyDown={(event) => {
                                  // Enter ACTIVATES (Space lifts) — the hook
                                  // treats both as lift, so Enter never reaches it.
                                  // On a link Enter is the browser's own.
                                  if (
                                    event.key === "Enter" &&
                                    reorder.activeId !== id
                                  ) {
                                    if (href) return;
                                    event.preventDefault();
                                    onCardActivate?.(item);
                                    return;
                                  }
                                  handleProps.onKeyDown(event);
                                  if (!event.defaultPrevented)
                                    handleCardKeyDown(event, column, index, id);
                                }}
                                // A link's click (and every modifier click)
                                // is the browser's: never prevented, never
                                // routed through onCardActivate.
                                onClick={
                                  href
                                    ? undefined
                                    : () => onCardActivate?.(item)
                                }
                                className={cn(
                                  "flex w-full min-w-0 flex-col gap-1 rounded-md border border-border bg-card p-3 text-start text-sm",
                                  "hover:bg-accent",
                                  // The grab cursor promises a pointer drag, so it appears
                                  // only where one can actually start: not in `readOnly`, and
                                  // not when the pointer path is off (`dragDisabled`, or below
                                  // the 768px breakpoint where the menu is the only path).
                                  // Previously every card claimed a drag a tablet could not
                                  // begin (audit B8-06).
                                  // A link keeps the browser's own cursor.
                                  canDrag
                                    ? "cursor-grab"
                                    : href
                                      ? undefined
                                      : "cursor-default",
                                )}
                              >
                                {/* One tab stop per card: truncated text in the
                                    content must not add its own. */}
                                <TruncationFocusProvider focusable={false}>
                                  {renderCard(item, column)}
                                </TruncationFocusProvider>
                              </BoardCardSurface>
                              {readOnly ? null : (
                                <DropdownMenu
                                  open={openMenuCard === id}
                                  onOpenChange={(open) =>
                                    setOpenMenuCard(open ? id : null)
                                  }
                                >
                                  <DropdownMenuTrigger
                                    render={
                                      <Button
                                        variant="ghost"
                                        size="icon-xs"
                                        aria-label={
                                          getItemLabel
                                            ? `${itemActions.length > 0 ? "Actions for" : "Move"} ${getItemLabel(item)}`
                                            : itemActions.length > 0
                                              ? "Card actions"
                                              : "Move card"
                                        }
                                        // The roving model's promise is ONE
                                        // card-layer tab stop per board — a
                                        // tabbable identically-named trigger
                                        // per card breaks it and scales with
                                        // board size. M (or Tab from the
                                        // active card) reaches the menu.
                                        tabIndex={rovingTarget === id ? 0 : -1}
                                        className="absolute end-1 top-1"
                                      >
                                        <EllipsisVertical />
                                      </Button>
                                    }
                                  />
                                  <DropdownMenuContent align="end">
                                    {itemActions.length > 0 ? (
                                      <>
                                        <RowActionMenuItems
                                          actions={itemActions}
                                        />
                                        <DropdownMenuSeparator />
                                      </>
                                    ) : null}
                                    {/* Within-column ordering — on touch the
                                        menu is the ONLY ordering path, so it
                                        must be lossless on its own. */}
                                    {[
                                      {
                                        label: "Move up",
                                        index: index - 1,
                                        enabled: index > 0,
                                      },
                                      {
                                        label: "Move down",
                                        index: index + 1,
                                        enabled:
                                          index < column.items.length - 1,
                                      },
                                      {
                                        label: "Move to top",
                                        index: 0,
                                        enabled: index > 0,
                                      },
                                      {
                                        label: "Move to bottom",
                                        index: column.items.length - 1,
                                        enabled:
                                          index < column.items.length - 1,
                                      },
                                    ].map((step) => (
                                      <DropdownMenuItem
                                        key={step.label}
                                        disabled={!step.enabled}
                                        onClick={() =>
                                          reorder.requestMove({
                                            id,
                                            from: {
                                              container: column.id,
                                              index,
                                            },
                                            to: {
                                              container: column.id,
                                              index: step.index,
                                            },
                                          })
                                        }
                                      >
                                        {step.label}
                                      </DropdownMenuItem>
                                    ))}
                                    {moveTargetsFor(id, column).map(
                                      ({ column: target, locked }) => (
                                        <DropdownMenuItem
                                          key={target.id}
                                          disabled={locked}
                                          onClick={() =>
                                            reorder.requestMove({
                                              id,
                                              from: {
                                                container: column.id,
                                                index,
                                              },
                                              to: {
                                                container: target.id,
                                                index: target.items.length,
                                              },
                                            })
                                          }
                                        >
                                          <span className="flex min-w-0 flex-col">
                                            <span className="truncate">
                                              Move to {laneLabel(target)}
                                            </span>
                                            {locked && target.lockedReason ? (
                                              <span className="text-xs text-muted-foreground">
                                                {target.lockedReason}
                                              </span>
                                            ) : null}
                                          </span>
                                        </DropdownMenuItem>
                                      ),
                                    )}
                                  </DropdownMenuContent>
                                </DropdownMenu>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    )}
                    {column.loading ? (
                      <div
                        aria-hidden="true"
                        data-slot="board-column-skeleton"
                        className="flex flex-col gap-2"
                      >
                        {[0, 1, 2].map((key) => (
                          <div
                            key={key}
                            className="flex flex-col gap-2 rounded-md border border-border bg-card p-3"
                          >
                            <Skeleton className="h-4 w-3/4" />
                            <Skeleton className="h-3 w-1/3" />
                          </div>
                        ))}
                      </div>
                    ) : null}
                    {column.loadMore ? (
                      <LoadMore {...column.loadMore} className="pt-1" />
                    ) : null}
                  </div>
                </ScrollArea>
              </CardContent>
            </Card>
          );
        })}
      </div>
      <reorder.Announcer />
    </div>
  );
}
